script.setup:
// PathFinding.js searches a generated maze; the scene records the order in which the finder
// expands cells (by wrapping grid.getNeighbors) and replays the search, then the path.
const mod = await ctx.utils.import("https://esm.sh/pathfinding@0.4.18");
const PF = mod.default ?? mod;
const COLS = 71, ROWS = 41;
// Recursive-backtracker maze on odd cells, then knock out some walls so there are loops.
const walls = Array.from({ length: ROWS }, () => new Array(COLS).fill(1));
const stack = [[1, 1]]; walls[1][1] = 0;
while (stack.length) {
  const [x, y] = stack[stack.length - 1];
  const next = [[2, 0], [-2, 0], [0, 2], [0, -2]].map(([dx, dy]) => [x + dx, y + dy, x + dx / 2, y + dy / 2])
    .filter(([nx, ny]) => nx > 0 && ny > 0 && nx < COLS - 1 && ny < ROWS - 1 && walls[ny][nx]);
  if (!next.length) { stack.pop(); continue; }
  const [nx, ny, wx, wy] = next[Math.floor(Math.random() * next.length)];
  walls[wy][wx] = 0; walls[ny][nx] = 0; stack.push([nx, ny]);
}
for (let y = 1; y < ROWS - 1; y++) for (let x = 1; x < COLS - 1; x++) {
  if (walls[y][x] && (x + y) % 2 === 1 && Math.random() < 0.1) walls[y][x] = 0;
}
const floor = [];
for (let y = 1; y < ROWS - 1; y++) for (let x = 1; x < COLS - 1; x++) if (!walls[y][x]) floor.push([x, y]);
const program = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
uniform vec2 u_resolution; uniform vec2 u_grid; uniform float u_cellPx; uniform sampler2D u_cells;
uniform float u_reveal; uniform float u_path; uniform vec2 u_head; uniform vec2 u_start; uniform vec2 u_goal; uniform float u_time;
uniform vec3 u_early; uniform vec3 u_late; uniform vec3 u_route;
void main(){
  vec2 g = (v_uv - 0.5) * u_resolution / u_cellPx + u_grid * 0.5;
  vec3 col = vec3(0.025, 0.027, 0.04);
  if (g.x >= 0.0 && g.y >= 0.0 && g.x < u_grid.x && g.y < u_grid.y) {
    vec4 c = texelFetch(u_cells, ivec2(g), 0);
    vec2 f = fract(g) - 0.5;
    float box = max(abs(f.x), abs(f.y));
    if (c.b > 0.5) {
      col = vec3(0.012, 0.014, 0.022);
    } else {
      col = vec3(0.1, 0.105, 0.14);
      if (c.r >= 0.0 && c.r <= u_reveal) {
        // Searched cells: colored by when they were expanded; the frontier glows.
        vec3 hue = mix(u_early, u_late, c.r);
        float front = exp(-(u_reveal - c.r) * 40.0);
        col = hue * (0.55 + 0.6 * front) + front * 0.3;
      }
      if (c.g >= 0.0 && c.g <= u_path) col = mix(col, u_route * (1.1 + 0.2 * sin(u_time * 6.0 - c.g * 40.0)), 0.9);
    }
  }
  float px = 1.0 / u_cellPx;
  float head = length(g - u_head - 0.5), start = length(g - u_start - 0.5), goal = length(g - u_goal - 0.5);
  col += u_route * exp(-head * head * 4.0) * 1.2;
  col = mix(col, vec3(0.3, 1.0, 0.6), smoothstep(0.42 + px, 0.42 - px, start));
  col = mix(col, vec3(1.0, 0.35, 0.55), smoothstep(0.42 + px, 0.42 - px, goal) * (0.75 + 0.25 * sin(u_time * 5.0)));
  outColor = vec4(col, 1.0);
}`);
Object.assign(ctx.state, { PF, COLS, ROWS, walls, floor, program, cells: new Float32Array(COLS * ROWS * 4), tex: null,
  start: [1, 1], goal: [COLS - 2, ROWS - 2], phase: "search", t: 0, finder: -1, moved: false, wasDown: false });
ctx.state.solve = () => {
  const s = ctx.state, grid = new PF.Grid(s.COLS, s.ROWS, s.walls);
  const order = [], getNeighbors = grid.getNeighbors.bind(grid);
  grid.getNeighbors = (node, diagonal) => { order.push(node); return getNeighbors(node, diagonal); };
  const opts = { heuristic: PF.Heuristic.manhattan };
  const finder = [new PF.AStarFinder(opts), new PF.DijkstraFinder(), new PF.BestFirstFinder(opts), new PF.BiAStarFinder(opts), new PF.BreadthFirstFinder()][ctx.uniforms.u_finder] ?? new PF.AStarFinder(opts);
  const path = finder.findPath(s.start[0], s.start[1], s.goal[0], s.goal[1], grid);
  for (let y = 0; y < s.ROWS; y++) for (let x = 0; x < s.COLS; x++) s.cells.set([-1, -1, s.walls[y][x], 0], (y * s.COLS + x) * 4);
  order.forEach((n, i) => { const o = (n.y * s.COLS + n.x) * 4; if (s.cells[o] < 0) s.cells[o] = i / Math.max(order.length - 1, 1); });
  path.forEach(([x, y], i) => { s.cells[(y * s.COLS + x) * 4 + 1] = i / Math.max(path.length - 1, 1); });
  s.tex = ctx.utils.uploadDataTexture(ctx.gl, s.tex, s.COLS, s.ROWS, s.cells);
  Object.assign(s, { path, expanded: order.length, phase: "search", t: 0 });
};
ctx.state.solve();

script.render:
const s = ctx.state, u = ctx.uniforms, [w, h] = ctx.resolution;
const cellPx = Math.min(w / s.COLS, h / s.ROWS) * 0.96;
if (u.u_finder !== s.finder) { s.finder = u.u_finder; s.solve(); }
// Click a floor cell to send the finder there (once the pointer has moved).
s.moved ||= ctx.mouse[0] !== 0.5 || ctx.mouse[1] !== 0.5;
if (s.moved && ctx.mouseDown && !s.wasDown) {
  const gx = Math.floor((ctx.mouse[0] - 0.5) * w / cellPx + s.COLS / 2), gy = Math.floor((0.5 - ctx.mouse[1]) * h / cellPx + s.ROWS / 2);
  if (gx > 0 && gy > 0 && gx < s.COLS - 1 && gy < s.ROWS - 1 && !s.walls[gy][gx]) {
    if (s.phase === "hold") s.start = s.goal;
    s.goal = [gx, gy]; s.solve();
  }
}
s.wasDown = ctx.mouseDown;
// Replay: the search (cells in expansion order), then the path, then a pause; then walk on.
s.t += ctx.dt;
const searchTime = s.expanded / (220 * u.u_speed), pathTime = s.path.length / (45 * u.u_speed);
let reveal = 1, along = 1;
if (s.phase === "search") { reveal = Math.min(1, s.t / searchTime); along = 0; if (s.t >= searchTime) { s.phase = "path"; s.t = 0; } }
else if (s.phase === "path") { along = Math.min(1, s.t / pathTime); if (s.t >= pathTime) { s.phase = "hold"; s.t = 0; } }
else if (s.t > 2.5) {
  s.start = s.goal;
  // Next goal: a random floor cell far enough away.
  let g; do g = s.floor[Math.floor(Math.random() * s.floor.length)]; while (Math.abs(g[0] - s.start[0]) + Math.abs(g[1] - s.start[1]) < (s.COLS + s.ROWS) / 2);
  s.goal = g; s.solve();
}
const k = s.path.length ? Math.min(s.path.length - 1, Math.floor(along * (s.path.length - 1))) : 0;
const head = s.path.length && s.phase !== "search" ? s.path[k] : [-99, -99];
const gl = ctx.gl;
gl.useProgram(s.program);
ctx.utils.bindTexture(s.program, "u_cells", s.tex, 0);
ctx.utils.drawFullscreen(s.program, { u_grid: [s.COLS, s.ROWS], u_cellPx: cellPx, u_reveal: reveal, u_path: s.phase === "search" ? -1 : along, u_head: head, u_start: s.start, u_goal: s.goal });
ctx.publish("expanded", s.expanded);
ctx.publish("path length", s.path.length);
